function applyStaticTranslations(){
 document.documentElement.lang=state.lang==="no"?"no":state.lang==="uk"?"uk":state.lang==="ru"?"ru":"en";
 document.querySelectorAll("[data-i18n]").forEach(el=>{const key=el.dataset.i18n;const value=t(key);if(value!==key)el.textContent=value;});
 const streak=document.querySelector(".streak-pill");
 if(streak){const spans=streak.querySelectorAll("span");if(spans.length>1)spans[1].textContent=t("dayStreak");}
 const nav=document.querySelector(".nav-list");
 if(nav)nav.setAttribute("aria-label",t("menu"));
 const close=document.querySelector("#mobileClose"),toggle=document.querySelector("#menuToggle");
 if(close)close.setAttribute("aria-label",state.lang==="ru"?"Закрыть меню":state.lang==="uk"?"Закрити меню":"Lukk meny");
 if(toggle)toggle.setAttribute("aria-label",state.lang==="ru"?"Открыть меню":state.lang==="uk"?"Відкрити меню":"Åpne meny");
}
