const LESSONS=[
 {id:1,level:"A1",emoji:"👋",titleKey:"lesson1",descKey:"lesson1d",words:[["Hello","Привет / Hei"],["My name is…","Меня зовут… / Jeg heter…"],["Nice to meet you","Приятно познакомиться / Hyggelig å møte deg"],["How are you?","Как дела? / Hvordan går det?"]],grammar:"Use “I am” to introduce yourself. In everyday speech, “I’m” is common.",examples:[["I am Alex.","Я Алекс. / Jeg er Alex."],["I'm from Norway.","Я из Норвегии. / Jeg kommer fra Norge."]],task:{q:"Choose the correct sentence:",a:["I is Maria.","I am Maria.","I are Maria."],c:1}},
 {id:2,level:"A1",emoji:"🎒",titleKey:"lesson2",descKey:"lesson2d",words:[["Book","Книга / Bok"],["Phone","Телефон / Telefon"],["Chair","Стул / Stol"],["Water","Вода / Vann"]],grammar:"Use “a” before a singular countable noun when it is not specific: a book, a chair.",examples:[["This is a book.","Это книга. / Dette er en bok."],["I have a phone.","У меня есть телефон. / Jeg har en telefon."]],task:{q:"Choose the correct phrase:",a:["a water","an phone","a book"],c:2}},
 {id:3,level:"A1",emoji:"🧩",titleKey:"lesson3",descKey:"lesson3d",words:[["I am","Я есть / Jeg er"],["You are","Ты есть / Du er"],["He is","Он есть / Han er"],["They are","Они есть / De er"]],grammar:"Use am with I, is with he/she/it, and are with you/we/they.",examples:[["She is happy.","Она счастлива. / Hun er glad."],["They are students.","Они студенты. / De er studenter."]],task:{q:"He ___ my friend.",a:["am","is","are"],c:1}},
 {id:4,level:"A2",emoji:"☀️",titleKey:"lesson4",descKey:"lesson4d",words:[["Wake up","Просыпаться / Våkne"],["Usually","Обычно / Vanligvis"],["Have breakfast","Завтракать / Spise frokost"],["Sometimes","Иногда / Noen ganger"]],grammar:"Use the present simple for habits and routines. Add -s to the verb with he, she and it.",examples:[["I wake up at seven.","Я просыпаюсь в семь. / Jeg våkner klokken sju."],["She works every day.","Она работает каждый день. / Hun jobber hver dag."]],task:{q:"He ___ breakfast at 8.",a:["have","has","having"],c:1}},
 {id:5,level:"B1",emoji:"🕰️",titleKey:"lesson5",descKey:"lesson5d",words:[["Experience","Опыт / Erfaring"],["Already","Уже / Allerede"],["Recently","Недавно / Nylig"],["Ever","Когда-либо / Noensinne"]],grammar:"Present perfect connects the past with the present: have/has + past participle.",examples:[["I have visited London.","Я бывал в Лондоне. / Jeg har besøkt London."],["She has already finished.","Она уже закончила. / Hun er allerede ferdig."]],task:{q:"I have never ___ sushi.",a:["eat","ate","eaten"],c:2}},
 {id:6,level:"B2",emoji:"🚀",titleKey:"lesson6",descKey:"lesson6d",words:[["Likely","Вероятно / Sannsynlig"],["Unless","Если не / Med mindre"],["Achievement","Достижение / Prestasjon"],["Opportunity","Возможность / Mulighet"]],grammar:"Use the first conditional for real future possibilities: If + present simple, will + verb.",examples:[["If it rains, we will stay home.","Если пойдёт дождь, мы останемся дома. / Hvis det regner, blir vi hjemme."],["Unless you hurry, you'll be late.","Если не поторопишься, опоздаешь. / Hvis du ikke skynder deg, kommer du for sent."]],task:{q:"If she studies, she ___ pass.",a:["would","will","has"],c:1}}
];
const $=s=>document.querySelector(s);
let state=loadState(), currentView="home", quizIndex=0, quizAnswers=[], currentLesson=null, taskAnswered=false;
let practiceItems=[], practiceIndex=0, practiceScore=0, practiceSkipped=0, practiceAnswered=false, practiceOrder=[];
let practiceLastCorrect=false;
function loadState(){try{const s=JSON.parse(localStorage.getItem("pingui_state"))||{};return {lang:["no","ru","uk"].includes(s.lang)?s.lang:"no",theme:s.theme==="dark"?"dark":"light",level:s.level||null,onboarded:!!s.onboarded,xp:s.xp||0,completed:s.completed||[],attempts:s.attempts||0,correct:s.correct||0,streak:s.streak||0,lastVisit:s.lastVisit||null,words:s.words||0}}catch{return {lang:"no",theme:"light",level:null,onboarded:false,xp:0,completed:[],attempts:0,correct:0,streak:0,lastVisit:null,words:0}}}
function save(){localStorage.setItem("pingui_state",JSON.stringify(state)); applyTheme();}
function applyTheme(){document.documentElement.dataset.theme=state.theme==="dark"?"dark":"light";}
function t(k){return (I18N[state.lang]&&I18N[state.lang][k])||I18N.no[k]||k}
function levelName(l){return t("level"+l)}
function localText(v){return typeof v==="string"?v:(v?.[state.lang]||v?.no||"")}
function setLang(l){if(!["no","ru","uk"].includes(l))return;state.lang=l;save();render()}
function updateStreak(){const today=new Date().toDateString();if(state.lastVisit!==today){const yesterday=new Date(Date.now()-86400000).toDateString();state.streak=state.lastVisit===yesterday?(state.streak||0)+1:1;state.lastVisit=today;save()}}
function showToast(msg){const el=$("#toast");el.textContent=msg;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),2200)}
function setView(v){currentView=v;document.querySelectorAll(".nav-item[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===v));render();$("#sidebar").classList.remove("open");window.scrollTo(0,0)}
function header(){const names={home:t("breadcrumbHome"),learn:t("navLearn"),practice:t("navPractice"),exercise:t("navPractice"),dictionary:t("navDictionary"),progress:t("navProgress"),settings:t("navSettings")};$("#breadcrumb").textContent=names[currentView]||t("breadcrumbHome");$("#streakCount").textContent=state.streak||0}
function render(){header();applyTheme();applyStaticTranslations();document.body.classList.toggle("testing-mode",currentView==="quiz");const root=$("#appContent");if(!state.onboarded){root.innerHTML=welcomeView();return}
 const views={home:homeView,learn:learnView,practice:practiceView,exercise:exerciseView,dictionary:dictionaryView,progress:progressView,settings:settingsView,quiz:quizView,result:resultView,lesson:lessonView};root.innerHTML=(views[currentView]||homeView)();bindDynamic()}
function welcomeView(){return `<div class="welcome-layout"><div class="welcome-card"><img class="welcome-mascot" src="assets/pingi.svg" alt="Pingi the penguin"><p class="eyebrow">WELCOME TO PINGUI</p><h1>${t("welcome")}</h1><p>${t("welcomeText")}</p><p class="eyebrow">${t("chooseLang")}</p><div class="language-row">${langButtons()}</div><div class="choice-grid" style="margin-top:26px"><button class="choice-card" data-onboard="beginner"><span class="choice-emoji">🌱</span><h3>${t("beginner")}</h3><p>${t("beginnerDesc")}</p></button><button class="choice-card" data-onboard="test"><span class="choice-emoji">🚀</span><h3>${t("know")}</h3><p>${t("knowDesc")}</p></button></div></div></div>`}
function langButtons(){return [["no","🇳🇴 Norsk"],["ru","🇷🇺 Русский"],["uk","🇺🇦 Українська"]].map(([id,label])=>`<button class="lang-button ${state.lang===id?"selected":""}" data-lang="${id}">${label}</button>`).join("")}
function homeView(){const done=state.completed.length;const next=LESSONS.find(l=>l.level===state.level&&!state.completed.includes(l.id))||LESSONS.find(l=>!state.completed.includes(l.id))||LESSONS[0];return `<div class="hero"><div class="hero-copy"><p class="eyebrow">${t("hello")}</p><h1>${t("hello")}</h1><p>${t("welcomeText")}</p><button class="btn btn-primary" data-open-lesson="${next.id}">${t("continue")} <span>→</span></button></div><div class="hero-art"><span class="spark one">✦</span><img class="hero-pingi-img" src="assets/pingi.svg" alt="Pingi the penguin"><span class="spark two">✧</span></div></div>
 <div class="stats-grid"><div class="stat-card"><div class="stat-icon blue">⚡</div><div><strong>${state.xp||0}</strong><span>${t("xp")}</span></div></div><div class="stat-card"><div class="stat-icon mint">✓</div><div><strong>${done}</strong><span>${t("lessons")} ${t("completed").toLowerCase()}</span></div></div><div class="stat-card"><div class="stat-icon peach">🔥</div><div><strong>${state.streak||0}</strong><span>${t("dayStreak")}</span></div></div></div>
 <div class="section-head"><div><p class="eyebrow">${t("beginnerPath")}</p><h2>${t("recommended")}</h2></div><button class="text-link" data-view="learn">${t("seeAll")} →</button></div>
 <div class="panel continue-card"><div class="lesson-icon">${next.emoji}</div><div class="continue-info"><strong>${t(next.titleKey)}</strong><p>${levelName(next.level)} · ${t("minutes")} 5</p><div class="progress-track"><div class="progress-fill" style="width:${done/LESSONS.length*100}%"></div></div></div><button class="btn btn-soft" data-open-lesson="${next.id}">${t("open")}</button></div>
 <div class="section-head"><div><p class="eyebrow">${t("level")} ${state.level}</p><h2>${t("learnTitle")}</h2></div></div><div class="path-grid">${LESSONS.filter(l=>l.level===state.level||LESSONS.find(x=>x.level===state.level)?.id>l.id).slice(0,3).map(lessonCard).join("")}</div>`}
function lessonCard(l){return `<article class="path-card"><div class="path-top"><span class="path-emoji">${l.emoji}</span><span class="level-tag">${l.level}</span></div><h3>${t(l.titleKey)}</h3><p>${t(l.descKey)}</p><div class="path-meta"><span>◷ 5 ${t("minutes")}</span><button class="text-link" data-open-lesson="${l.id}">${t("open")} →</button></div></article>`}
function learnView(){return `<p class="eyebrow">${t("yourLevel")}: ${state.level} · ${levelName(state.level)}</p><h1 class="page-title">${t("learnTitle")}</h1><p class="subheading">${t("learnText")}</p><div class="section-head"><h2>${t("allLevels")}</h2><button class="text-link" data-view="settings">${t("changeLevel")} →</button></div><div class="path-grid">${LESSONS.map(lessonCard).join("")}</div>`}
function practiceView(){
 const levels=["A1","A2","B1","B2","C1"];
 const skills=["vocabulary","grammar","translation","sentence","mixed"];
 const skillLabel={vocabulary:t("vocabSkill"),grammar:t("grammarSkill"),translation:t("translationSkill"),sentence:t("sentenceSkill"),mixed:t("mixedSkill")};
 const total=PRACTICE_BANK.length;
 return `<div class="practice-hero"><div><p class="eyebrow">PINGUI LAB · ${total} ${t("tasksAvailable")}</p><h1 class="page-title">${t("practiceTitle")}</h1><p class="subheading">${t("practiceIntro")}</p><div class="practice-pills"><span>🐧 ${t("perSet")}</span><span>⚡ +5 XP ${t("correct").toLowerCase()}</span><span>📚 A1–C1</span></div></div><img src="assets/pingi.svg" alt="Pingi"></div>
 <div class="practice-builder panel"><div class="section-head"><div><p class="eyebrow">${t("levelFocus")}</p><h2>${t("skillFocus")}</h2></div><span class="practice-count">${total} ${t("tasksAvailable")}</span></div>
 <div class="practice-filters"><label><span>${t("levelFocus")}</span><select id="practiceLevel"><option value="all">${t("allLevelsFilter")}</option>${levels.map(l=>`<option value="${l}" ${state.level===l?"selected":""}>${l} · ${levelName(l)}</option>`).join("")}</select></label>
 <label><span>${t("skillFocus")}</span><select id="practiceCategory"><option value="all">${t("allSkills")}</option>${skills.map(k=>`<option value="${k}">${skillLabel[k]}</option>`).join("")}</select></label></div>
 <div class="practice-category-grid">${skills.map((k,i)=>{const icons=["🔤","🧠","🌍","🧩","🎯"];const count=PRACTICE_BANK.filter(x=>x.category===k).length;return `<button class="practice-category" data-category-pick="${k}"><span class="category-icon">${icons[i]}</span><strong>${skillLabel[k]}</strong><small>${count} ${t("tasksAvailable")}</small><span class="category-arrow">→</span></button>`}).join("")}</div>
 <button class="btn btn-primary practice-start" data-start-practice>${t("startPractice")} →</button></div>
 <div class="practice-lower-grid"><article class="practice-info-card"><span class="info-icon">🧭</span><h3>${t("levelFocus")}</h3><p>${t("practiceIntro")}</p><div class="level-chip-row">${levels.map(l=>`<span>${l}</span>`).join("")}</div></article><article class="practice-info-card"><span class="info-icon">🏅</span><h3>${t("progressTitle")}</h3><p>${state.attempts?Math.round(state.correct/state.attempts*100):0}% · ${t("accuracyLabel")}</p><div class="progress-track"><div class="progress-fill" style="width:${state.attempts?Math.round(state.correct/state.attempts*100):0}%"></div></div><small>${state.attempts} ${t("answered").toLowerCase()}</small></article></div>`;
}
function startPracticeSession(){
 const level=$("#practiceLevel")?.value||"all", category=$("#practiceCategory")?.value||"all";
 let pool=PRACTICE_BANK.filter(x=>(level==="all"||x.level===level)&&(category==="all"||x.category===category));
 if(!pool.length){showToast(t("noTasks"));return}
 pool=pool.slice().sort(()=>Math.random()-.5);
 practiceItems=pool.slice(0,Math.min(10,pool.length));practiceIndex=0;practiceScore=0;practiceSkipped=0;practiceAnswered=false;practiceOrder=[];currentView="exercise";render();
}
function exerciseView(){
 if(practiceIndex>=practiceItems.length)return practiceResultView();
 const item=practiceItems[practiceIndex], prompt=localText(item.prompt), hint=localText(item.hint);
 const options=item.type==="mcq"?`<div class="exercise-options" role="group" aria-label="${t("chooseOption")}">${item.options.map((o,i)=>`<button type="button" class="exercise-option" data-exercise-option="${i}" aria-pressed="false">${o}</button>`).join("")}</div>`:"";
 const input=item.type==="text"?`<input class="exercise-input" id="exerciseInput" type="text" autocomplete="off" placeholder="${t("yourAnswer")}" ${practiceAnswered?"disabled":""}>`:"";
 const order=item.type==="order"?`<div class="order-answer" id="orderAnswer">${practiceOrder.map((w,i)=>`<button class="order-token selected" data-order-remove="${i}" ${practiceAnswered?"disabled":""}>${w}</button>`).join("")||`<span class="order-placeholder">${t("buildSentence")}</span>`}</div><div class="order-bank">${item.options.map((w,i)=>{const used=practiceOrder.filter((x,j)=>practiceOrder.indexOf(x)===j&&false);return `<button class="order-token" data-order-token="${i}" ${practiceAnswered?"disabled":""}>${w}</button>`}).join("")}</div><button class="text-link order-reset" data-order-reset ${practiceAnswered?"disabled":""}>↺ ${t("tryAgain")}</button>`:"";
 const feedback=practiceAnswered?`<div class="exercise-feedback ${practiceLastCorrect?"good":"bad"}"><strong>${practiceLastCorrect?t("correctFeedback"):t("wrongFeedback")}</strong><p><b>${t("correctAnswer")}:</b> ${item.answer}</p><p><b>${t("explanation")}:</b> ${localText(item.explain)}</p></div>`:"";
 return `<div class="exercise-shell"><div class="exercise-top"><button class="text-link" data-view="practice">← ${t("backPractice")}</button><span>${item.level} · ${t(item.category==="vocabulary"?"vocabSkill":item.category==="grammar"?"grammarSkill":item.category==="translation"?"translationSkill":item.category==="sentence"?"sentenceSkill":"mixedSkill")}</span></div><div class="exercise-progress-row"><span>${t("questionLabel")} ${practiceIndex+1} / ${practiceItems.length}</span><span>⚡ ${practiceScore*5} XP</span></div><div class="progress-track"><div class="progress-fill" style="width:${(practiceIndex+(practiceAnswered?1:0))/practiceItems.length*100}%"></div></div><article class="exercise-card"><div class="exercise-mascot"><img src="assets/pingi.svg" alt="Pingi"><span>${hint}</span></div><p class="eyebrow">${item.level} · ${t("questionLabel").toUpperCase()}</p><h1>${prompt}</h1>${item.type==="mcq"?`<p class="subheading">${t("chooseOption")}</p>`:""}${options}${input}${order}${feedback}<div class="exercise-actions">${!practiceAnswered?`<button class="btn btn-primary" data-exercise-check>${t("checkAnswer")}</button><button class="text-link" data-exercise-skip>${t("skipTask")}</button>`:`<button class="btn btn-primary" data-exercise-next>${practiceIndex===practiceItems.length-1?t("finishSet"):t("nextTask")} →</button>`}</div></article></div>`;
}

function practiceResultView(){
 const total=practiceItems.length, attempted=total-practiceSkipped, pct=attempted?Math.round(practiceScore/attempted*100):0;
 return `<div class="practice-result"><div class="result-pingi"><img src="assets/pingi.svg" alt="Pingi"></div><p class="eyebrow">PINGUI LAB</p><h1>${t("sessionComplete")}</h1><p class="subheading">${t("sessionScore")}</p><div class="result-stats"><div><strong>${practiceScore}/${attempted}</strong><span>${t("correct")}</span></div><div><strong>${pct}%</strong><span>${t("accuracyLabel")}</span></div><div><strong>${practiceScore*5}</strong><span>${t("xpBonus")}</span></div></div><p class="subheading">${t("skippedLabel")}: ${practiceSkipped}</p><button class="btn btn-primary" data-practice-again>${t("tryAgainSet")}</button><button class="text-link" data-view="practice">${t("backPractice")}</button></div>`;
}
function checkPracticeAnswer(){
 if(practiceAnswered)return;
 const item=practiceItems[practiceIndex];let answer="";
 if(item.type==="mcq"){const selected=document.querySelector("[data-exercise-option].selected");if(!selected){showToast(t("chooseOption"));return}answer=item.options[Number(selected.dataset.exerciseOption)];}
 else if(item.type==="text"){answer=$("#exerciseInput")?.value.trim()||"";if(!answer){showToast(t("yourAnswer"));return}}
 else answer=practiceOrder.join(" ");
 const norm=x=>String(x).toLowerCase().replace(/[’']/g,"'").replace(/[.,!?;:]/g,"").replace(/\s+/g," ").trim();
 practiceLastCorrect=norm(answer)===norm(item.answer);
 practiceAnswered=true;
 if(practiceLastCorrect){practiceScore++;state.correct++;state.xp+=5}
 state.attempts++;save();render();
}
function advancePractice(){practiceIndex++;practiceAnswered=false;practiceOrder=[];if(practiceIndex>=practiceItems.length){currentView="exercise";render()}else render()}
function dictionaryView(){return `<p class="eyebrow">${t("navDictionary")}</p><h1 class="page-title">${t("dictionaryTitle")}</h1><p class="subheading">${t("dictionaryText")}</p><div class="dictionary-toolbar"><input class="dictionary-search" id="dictionarySearch" type="search" placeholder="${t("searchWords")}" aria-label="${t("searchWords")}"><span class="dictionary-count" id="dictionaryCount">${VOCAB.length} ${t("wordCount")}</span></div><div class="dictionary-grid" id="dictionaryGrid">${VOCAB.map(v=>`<article class="dictionary-word"><strong>${v.en}</strong><span>${v[state.lang]}</span></article>`).join("")}</div>`}
function progressView(){const accuracy=state.attempts?Math.round(state.correct/state.attempts*100):0;return `<p class="eyebrow">${t("progressEyebrow")}</p><h1 class="page-title">${t("progressTitle")}</h1><p class="subheading">${t("progressText")}</p><div class="stats-grid"><div class="stat-card"><div class="stat-icon blue">⚡</div><div><strong>${state.xp||0}</strong><span>${t("xp")}</span></div></div><div class="stat-card"><div class="stat-icon mint">✓</div><div><strong>${state.completed.length}</strong><span>${t("lessonsDone")}</span></div></div><div class="stat-card"><div class="stat-icon peach">◎</div><div><strong>${accuracy}%</strong><span>${t("accuracy")}</span></div></div></div><div class="section-head"><h2>${t("currentLevel")}: ${state.level}</h2></div><div class="progress-large"><div class="progress-panel"><h3>${t("beginnerPath")}</h3><div class="level-bars">${LEVELS.map((l,i)=>{const count=LESSONS.filter(x=>x.level===l&&state.completed.includes(x.id)).length;const total=LESSONS.filter(x=>x.level===l).length;return `<div class="level-bar-row"><span>${l}</span><div class="progress-track"><div class="progress-fill" style="width:${total?count/total*100:0}%"></div></div><em>${count}/${total}</em></div>`}).join("")}</div></div><div class="progress-panel"><h3>🐧 ${t("tipTitle")}</h3><p class="subheading">${t("tipText")}</p><div style="font-size:44px;text-align:center;margin-top:22px">🏅</div><p style="text-align:center;font-weight:800;font-size:12px">${state.completed.length} / ${LESSONS.length} ${t("lessons")}</p></div></div>`}
function settingsView(){return `<p class="eyebrow">${t("settingsEyebrow")}</p><h1 class="page-title">${t("settingsTitle")}</h1><p class="subheading">${t("settingsText")}</p><div class="panel" style="margin-top:24px"><div class="setting-row"><div><strong>${t("interface")}</strong><p>${t("chooseLang")}</p></div><div class="language-row" style="margin:0">${langButtons()}</div></div><div class="setting-row"><div><strong>${t("theme")}</strong><p>${t("lightTheme")} / ${t("darkTheme")}</p></div><select class="select" id="themeSelect"><option value="light" ${state.theme!=="dark"?"selected":""}>☀️ ${t("lightTheme")}</option><option value="dark" ${state.theme==="dark"?"selected":""}>🌙 ${t("darkTheme")}</option></select></div><div class="setting-row"><div><strong>${t("currentLevel")}</strong><p>${levelName(state.level)} (${state.level})</p></div><select class="select" id="levelSelect">${LEVELS.map(l=>`<option value="${l}" ${state.level===l?"selected":""}>${l} · ${levelName(l)}</option>`).join("")}</select></div><div class="setting-row"><div><strong>${t("startOver")}</strong><p>${t("testText")}</p></div><button class="btn btn-soft" data-action="retake">${t("takeTest")}</button></div><div class="setting-row"><div><strong>${t("authSignout")}</strong><p>${t("authProfileRequired")}</p></div><button class="btn btn-light" data-auth-signout>${t("authSignout")}</button></div><div class="setting-row"><div><strong>${t("reset")}</strong><p>${t("resetText")}</p></div><button class="btn btn-light" data-action="reset">${t("reset")}</button></div></div>`}
function quizView(){const q=QUESTIONS[quizIndex];const answered=quizAnswers.filter(x=>x!==null&&x!==undefined).length;return `<div class="quiz-standalone"><div class="quiz-brand"><span>🐧</span> PINGUI <small>LEVEL CHECK</small></div><div class="quiz-wrap"><div class="quiz-top"><span>${t("question")} ${quizIndex+1} ${t("of")} ${QUESTIONS.length}</span><span>${q.l} · ${levelName(q.l)}</span></div><div class="quiz-progress"><div style="width:${((quizIndex+1)/QUESTIONS.length)*100}%"></div></div><div class="quiz-card"><p class="eyebrow">${t("testTitle")}</p><h2>${q.q[state.lang]||q.q.no}</h2><p class="quiz-hint">${t("testText")}</p><div class="answers">${q.a.map((a,i)=>`<button class="answer-option ${quizAnswers[quizIndex]===i?"selected":""}" data-answer="${i}"><span class="answer-letter">${String.fromCharCode(65+i)}</span>${a}</button>`).join("")}</div><div class="quiz-actions"><span class="quiz-counter">${answered} ${t("answeredOf")} ${QUESTIONS.length}</span><div class="quiz-buttons"><button class="btn btn-light" data-action="quizSkip">${t("skip")}</button><button class="btn btn-primary" data-action="quizNext" ${quizAnswers[quizIndex]===undefined||quizAnswers[quizIndex]===null?"disabled":""}>${quizIndex===QUESTIONS.length-1?t("finish"):t("next")}</button></div></div></div><p class="quiz-footnote">🐧 ${t("resultText")}</p></div></div>`}
function resultView(){const answered=quizAnswers.filter(a=>a!==null&&a!==undefined).length;const score=quizAnswers.reduce((n,a,i)=>n+(a!==null&&a!==undefined&&a===QUESTIONS[i].c?1:0),0);const pct=answered?score/answered:0;let level="A1";for(const l of LEVELS){const ids=QUESTIONS.map((q,i)=>q.l===l?i:-1).filter(i=>i>=0);const valid=ids.filter(i=>quizAnswers[i]!==null&&quizAnswers[i]!==undefined);const hits=valid.filter(i=>quizAnswers[i]===QUESTIONS[i].c).length;if(valid.length>=3&&hits/valid.length>=.6)level=l;}return `<div class="result-card"><img class="welcome-mascot" src="assets/pingi.svg" alt="Pingi the penguin"><p class="eyebrow">${t("wellDone")}</p><h1>${t("resultTitle")}</h1><div class="level-circle">${level}</div><h2 style="font:800 18px 'Nunito',sans-serif;margin:0">${levelName(level)}</h2><p>${t("resultText")}</p><div class="result-breakdown"><div><strong>${score}/${answered}</strong><span>${t("correct")}</span></div><div><strong>${answered}/${QUESTIONS.length}</strong><span>${t("answered")}</span></div><div><strong>${Math.round(pct*100)}%</strong><span>${t("score")}</span></div></div><button class="btn btn-primary" data-action="saveLevel" data-level="${level}">${t("startPath")} →</button><button class="btn btn-light" style="margin-left:7px" data-view="home">${t("home")}</button></div>`}
function lessonView(){const l=currentLesson;if(!l)return `<p>${t("noLesson")}</p>`;return `<p class="eyebrow">${t("lesson")} ${l.id} · ${l.level}</p><div class="lesson-layout"><div><div class="lesson-main"><div style="font-size:40px;margin-bottom:12px">${l.emoji}</div><h1>${t(l.titleKey)}</h1><p class="lead">${t(l.descKey)}</p><div class="lesson-block"><h3>📚 ${t("vocab")}</h3>${l.words.map(w=>`<div class="example-row"><strong>${w[0]}</strong><span>${w[1]}</span></div>`).join("")}</div><div class="lesson-block"><h3>💡 ${t("grammar")}</h3><p class="subheading">${l.grammar}</p><h3 style="margin-top:16px">${t("example")}</h3>${l.examples.map(w=>`<div class="example-row"><strong>${w[0]}</strong><span>${w[1]}</span></div>`).join("")}</div></div><div class="task-card"><p class="eyebrow">${t("tryIt")}</p><h3>${t("task")}</h3><p>${l.task.q}</p><div class="task-options">${l.task.a.map((a,i)=>`<button class="task-option" data-task-answer="${i}">${a}</button>`).join("")}</div><div class="feedback" id="taskFeedback"></div><button class="btn btn-primary" style="margin-top:13px;width:100%" id="completeLesson" disabled>${t("completeLesson")} +20 XP</button></div></div><aside class="lesson-side"><div class="tip-card"><div class="tip-pingi">🐧</div><strong>${t("tipTitle")}</strong><p>${t("tipText")}</p></div><div class="panel"><p class="eyebrow">${t("yourLevel")}</p><h2 style="font:900 25px 'Nunito',sans-serif;margin:0">${state.level}</h2><p class="subheading">${levelName(state.level)}</p></div></aside></div>`}
function bindDynamic(){/* delegated handlers are attached once below */}
// Exercise choice selection is handled in capture phase for reliability and keyboard/screen-reader state.
document.addEventListener("click",e=>{
 const target=e.target instanceof Element?e.target:null;
 const option=target?.closest("[data-exercise-option]");
 if(!option||practiceAnswered)return;
 e.preventDefault();e.stopPropagation();
 document.querySelectorAll("[data-exercise-option]").forEach(button=>{
   button.classList.remove("selected");button.setAttribute("aria-pressed","false");
 });
 option.classList.add("selected");option.setAttribute("aria-pressed","true");
},true);
function startQuiz(){quizIndex=0;quizAnswers=[];currentView="quiz";render()}
function openLesson(id){currentLesson=LESSONS.find(l=>l.id===Number(id));taskAnswered=false;currentView="lesson";render()}
function finishQuiz(){currentView="result";render()}
document.addEventListener("click",e=>{
 const lang=e.target.closest("[data-lang]");if(lang){setLang(lang.dataset.lang);return}
 const view=e.target.closest("[data-view]");if(view){setView(view.dataset.view);return}
 const onboard=e.target.closest("[data-onboard]");if(onboard){state.onboarded=true;if(onboard.dataset.onboard==="beginner"){state.level="A1";save();setView("home")}else startQuiz();return}
 const open=e.target.closest("[data-open-lesson]");if(open){openLesson(open.dataset.openLesson);return}
 const answer=e.target.closest("[data-answer]");if(answer){quizAnswers[quizIndex]=Number(answer.dataset.answer);render();return}
 const act=e.target.closest("[data-action]");if(act){const a=act.dataset.action;if(a==="home")setView("home");if(a==="quizNext"){if(quizIndex<QUESTIONS.length-1){quizIndex++;render()}else finishQuiz()}if(a==="quizSkip"){quizAnswers[quizIndex]=null;if(quizIndex<QUESTIONS.length-1){quizIndex++;render()}else finishQuiz()}if(a==="quizBack"){quizIndex=Math.max(0,quizIndex-1);render()}if(a==="saveLevel"){state.level=act.dataset.level;state.onboarded=true;save();setView("home")}if(a==="retake")startQuiz();if(a==="reset"){if(confirm(t("confirmReset"))){localStorage.removeItem("pingui_state");state=loadState();render();showToast(t("resetDone"))}}return}
 const pr=e.target.closest("[data-practice]");if(pr){return}
 const cat=e.target.closest("[data-category-pick]");if(cat){const select=$("#practiceCategory");if(select)select.value=cat.dataset.categoryPick;startPracticeSession();return}
 if(e.target.closest("[data-start-practice]")){startPracticeSession();return}
 const token=e.target.closest("[data-order-token]");if(token&&!practiceAnswered){const item=practiceItems[practiceIndex];const word=item.options[Number(token.dataset.orderToken)];const used=practiceOrder.filter(x=>x===word).length;const total=item.options.filter(x=>x===word).length;if(used<total){practiceOrder.push(word);render()}return}
 const removeToken=e.target.closest("[data-order-remove]");if(removeToken&&!practiceAnswered){practiceOrder.splice(Number(removeToken.dataset.orderRemove),1);render();return}
 if(e.target.closest("[data-order-reset]")){practiceOrder=[];render();return}
 if(e.target.closest("[data-exercise-check]")){checkPracticeAnswer();return}
 if(e.target.closest("[data-exercise-next]")){advancePractice();return}
 if(e.target.closest("[data-exercise-skip]")){practiceSkipped++;advancePractice();return}
 if(e.target.closest("[data-practice-again]")){startPracticeSession();return}
 const task=e.target.closest("[data-task-answer]");if(task&&currentLesson){const correct=Number(task.dataset.taskAnswer)===currentLesson.task.c;state.attempts++;if(correct)state.correct++;save();
  if(correct){document.querySelectorAll("[data-task-answer]").forEach((b,i)=>{b.disabled=true;b.classList.remove("wrong");if(i===currentLesson.task.c)b.classList.add("correct")});taskAnswered=true;$("#completeLesson").disabled=false;}
  else {task.classList.add("wrong");taskAnswered=false;$("#completeLesson").disabled=true;}
  $("#taskFeedback").textContent=correct?t("correctFeedback"):t("wrongFeedback");$("#taskFeedback").className="feedback "+(correct?"good":"bad");return}
 if(e.target.closest("#completeLesson")){if(!state.completed.includes(currentLesson.id)){state.completed.push(currentLesson.id);state.xp+=20;state.words+=currentLesson.words.length;save()}showToast(t("wellDone")+" +20 XP");setView("learn");return}
});
document.addEventListener("input",e=>{if(e.target.id==="dictionarySearch"){const term=e.target.value.trim().toLowerCase();const filtered=VOCAB.filter(v=>v.en.toLowerCase().includes(term)||v[state.lang].toLowerCase().includes(term));$("#dictionaryGrid").innerHTML=filtered.map(v=>`<article class="dictionary-word"><strong>${v.en}</strong><span>${v[state.lang]}</span></article>`).join("")||`<p class="subheading">${t("noData")}</p>`;$("#dictionaryCount").textContent=filtered.length+" "+t("wordCount");}});
document.addEventListener("change",e=>{if(e.target.id==="themeSelect"){state.theme=e.target.value;save();showToast(t("saved"));}if(e.target.id==="levelSelect"){state.level=e.target.value;save();showToast(t("levelSaved"));}});
$("#menuToggle").addEventListener("click",()=>$("#sidebar").classList.add("open"));$("#mobileClose").addEventListener("click",()=>$("#sidebar").classList.remove("open"));$("#profileButton").addEventListener("click",()=>setView("settings"));
if(!["no","ru","uk"].includes(state.lang)){state.lang="no";save()}updateStreak();render();
